/* Signature Shona Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Tendaimoyo": "From tendai (thanks) + moyo (heart): 'thankful heart'.", "Rudofarai": "From rudo (love) + farai (rejoice): 'joyful love'.", "Tatendanyasha": "From tatenda + nyasha (grace).", "Chiporudo": "From chipo (gift) + rudo (love): 'gift of love'.", "Faraitenda": "From farai + tendai.", "Nyasharudo": "From nyasha + rudo: 'graceful love'.", "Moyorudo": "Signature surname: 'heart of love'.", "Tendaimoyoza": "Signature surname.", "Farainyasha": "Signature surname.", "Rudomoyo": "Signature surname: 'love heart'."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Tendaimoyo';
console.log(lookup(q));

